    {
        var directory = CrossRuntimeReviewPaths.DesignDirectory(repoRoot, executionUnit);
        var relativeDirectory = CrossRuntimeReviewPaths.DesignRelativeDirectory(executionUnit);
        if (!Directory.Exists(directory))
        {
