        Require(File.Exists(rawPath), $"raw verdict copy '{expectedRaw}' is missing.");
        Require(string.Equals(CrossRuntimeReviewStore.Sha256Hex(File.ReadAllBytes(rawPath)), record.RawVerdictSha256, StringComparison.Ordinal),
