// data-driven ReviewStandingPolicy registry, so a domain can override them
// through an optional `.intent-cli/review-policy.json` without changing
// code. The default reproduces the prior G445 rules verbatim, keeping a
// host with no policy file byte-identical to before.
private static IReadOnlyList<string> DeviceGatedEvidencePolicy =>
    ReviewStandingPolicy.DefaultDeviceGatedEvidenceRules;

private static readonly IReadOnlyList<string> DefaultValidationSuggestions = new[]
{
    "Run focused tests named in the packet's Verification section.",
    "Run `git diff --check` against the merge result.",
    "Confirm the PR head SHA before and after the review pass.",
    // G316: validation is not just test execution.
    "After tests pass, restate at least one packet contract clause AND one intent reference touched by the diff in your approval summary; if you cannot, treat the PR as request-update."
};

// G696: GitHub rejects an approval from the same account that authored the
// PR. The review surface makes the valid verdict/report pair explicit so
// a review seat does not fall back to an unsanctioned comment command or
// silently treat the rejected approval as completion.
private static readonly GuideReviewSameAccountVerdictConvention SameAccountVerdict = new()
{
    GithubApproveRejectedForSameAccount = true,
    Verdict = "COMMENTED",
    ReviewCommand = "gh pr review --body-file <review.md> --comment",
    ReportCommand = "intent-cli notify report --domain <domain> --team <team> --from review --to orchestration --task-id <task-id> --status <completed|blocked|question> --artifact <artifact> --summary <one-line-summary> --routing-root <host-root> --write --format json",
    Summary = "When the review author is the PR author's same GitHub account, `gh pr review --approve` is rejected by GitHub. Submit a COMMENTED review with the sanctioned body-file form, then emit the canonical intent-cli notify report; the report carries the workflow verdict.",
};

// G834: cross-runtime implementation review for declared teams. Distinct
// from the G789 seat-kind "cross-review" guidance. Rendered as a Markdown
// section only, so the pinned G789 JSON payload shape is unchanged.
internal static readonly IReadOnlyList<string> CrossRuntimeReviewRules = new[]
{
    "Required only for a team declared in `[[cross_runtime_review.teams]]` of the host `.intent-cli/config.toml`, and only for PRs in that declaration's `repos`; undeclared teams need only the independent same-runtime subagent review.",
    "From the host root, render the request: `intent-cli review cross-runtime request --repo <owner/repo> --pr <n> --head-sha <head-sha> --execution-unit <unit> --runtime codex|claude|cursor --clone <read-only-clone> --out-dir <dir>`. The seat runs the rendered `invocation.txt` itself in a read-only clone; intent-cli never runs it.",
    "Record both verdicts on the same head — the same-runtime review (a request rendered for the declared conductor runtime and run by the seat, since claude and cursor verdicts must be the pinned invocation envelope) and the cross-runtime review — with `intent-cli review cross-runtime record ... --kind implementation --runtime <runtime> --runtime-version <version> --verdict-file <file> --write`, then post each rendered comment with `gh pr review <n> --comment --body-file <file>`.",
    "Read-only enforcement differs by runtime (measured): codex `-s read-only` is sandbox-enforced; the claude invocation removes only the Edit, Write, and NotebookEdit tools, so the Claude reviewer may run commands such as tests and shell-level writes are not sandbox-enforced; cursor `--mode ask` refuses every non-read-only tool, including shell commands, so the Cursor reviewer reads files but cannot run git or tests.",
    "A blocking finding from either reviewer stops merge. After the fix, the runtime that raised it re-reviews the new head; a superseding approve on the same head must come from a fresh reviewer run, not a repeated prompt to the same session.",
    "`intent-cli review cross-runtime status --repo <owner/repo> --pr <n> --head-sha <head-sha> --execution-unit <unit>` shows the gate that `automation pr-transition --transition approved --head-sha <head-sha>` applies. The gate assumes an honest seat; it is not a security boundary.",
    "Confirming each vendor's automation terms for headless reviewer runs is the operator's responsibility. intent-cli renders requests and records verdicts only; it does not start, launch, or manage any reviewer.",
};

public static int Execute(CliContext context, string[] args, TextWriter writer)
{
    ArgumentNullException.ThrowIfNull(context);
    ArgumentNullException.ThrowIfNull(args);
    ArgumentNullException.ThrowIfNull(writer);

    if (args.Length == 1 && string.Equals(args[0], "--help", StringComparison.Ordinal))
    {
        WriteHelp(writer);
        return 0;
    }

    if (!TryParseArguments(args, out var pr, out var repo, out var domainOverride, out var format, out var error))
    {
        writer.WriteLine(error);
        writer.WriteLine(UsageLine);
        return 1;
    }

